import type { ReactNode } from "react"

import type { AttemptStatus, ContextMode, TaskStatus, ThreadRef } from "@/lib/agent-task-types"
import { cn } from "@/lib/utils"
import { StatusPill, type StatusPillProps, type StatusTone } from "@/components/ui/status-pill"
import { TaskStatusIcon, taskStatusAccentTones, type TaskStatusIconProps } from "@/components/ui/task-status-icon"

const taskStatusTones: Record<TaskStatus, StatusTone> = {
  proposed: "warning",
  todo: "neutral",
  working: "info",
  review: "warning",
  blocked: "destructive",
  done: "success",
  cancelled: "muted",
}

const taskStatusLabels: Record<TaskStatus, string> = {
  proposed: "Proposed",
  todo: "To do",
  working: "Working",
  review: "In review",
  blocked: "Blocked",
  done: "Done",
  cancelled: "Cancelled",
}

const taskStatusLabelsEs: Record<TaskStatus, string> = {
  proposed: "Propuesta",
  todo: "Pendiente",
  working: "En curso",
  review: "En revisión",
  blocked: "Bloqueada",
  done: "Hecha",
  cancelled: "Cancelada",
}

const attemptStatusTones: Record<AttemptStatus, StatusTone> = {
  dispatching: "neutral",
  active: "info",
  succeeded: "success",
  failed: "destructive",
  cancelled: "muted",
  superseded: "muted",
  unknown: "muted",
}

const attemptStatusLabels: Record<AttemptStatus, string> = {
  dispatching: "Dispatching",
  active: "Active",
  succeeded: "Succeeded",
  failed: "Failed",
  cancelled: "Cancelled",
  superseded: "Superseded",
  unknown: "Unknown",
}

const attemptStatusLabelsEs: Record<AttemptStatus, string> = {
  dispatching: "Enviando",
  active: "Activo",
  succeeded: "Correcto",
  failed: "Fallido",
  cancelled: "Cancelado",
  superseded: "Sustituido",
  unknown: "Desconocido",
}

const contextModeTones: Record<ContextMode, StatusTone> = {
  fresh: "neutral",
  reuse: "info",
  fork: "info",
  compact: "neutral",
}

type ContextModeLabels = Record<ContextMode, string> & {
  /** Precedes the source thread, as in "Fork from Index docs". */
  from: string
}

const contextModeLabels: ContextModeLabels = {
  fresh: "Fresh context",
  reuse: "Reused context",
  fork: "Forked context",
  compact: "Compacted context",
  from: "from",
}

const contextModeLabelsEs: ContextModeLabels = {
  fresh: "Contexto nuevo",
  reuse: "Contexto reutilizado",
  fork: "Contexto bifurcado",
  compact: "Contexto compactado",
  from: "de",
}

type PillProps<Status extends string> = Omit<StatusPillProps, "tone" | "children"> & {
  status: Status
  labels?: Partial<Record<Status, string>>
}

function TaskStatusPill({ status, labels, ...props }: PillProps<TaskStatus>) {
  return (
    <StatusPill data-status={status} tone={taskStatusTones[status]} {...props}>
      {labels?.[status] ?? taskStatusLabels[status]}
    </StatusPill>
  )
}

function AttemptStatusPill({ status, labels, ...props }: PillProps<AttemptStatus>) {
  return (
    <StatusPill data-status={status} tone={attemptStatusTones[status]} {...props}>
      {labels?.[status] ?? attemptStatusLabels[status]}
    </StatusPill>
  )
}

type ContextModePillProps = Omit<StatusPillProps, "tone" | "children"> & {
  mode: ContextMode
  /** Shown for "reuse" and "fork". */
  sourceThread?: ThreadRef
  renderThreadLink?: (thread: ThreadRef) => ReactNode
  labels?: Partial<ContextModeLabels>
}

function ContextModePill({
  mode,
  sourceThread,
  renderThreadLink,
  labels: labelOverrides,
  className,
  ...props
}: ContextModePillProps) {
  const labels = { ...contextModeLabels, ...labelOverrides }
  const source = (mode === "reuse" || mode === "fork") && sourceThread
  const pill = (
    <StatusPill data-mode={mode} tone={contextModeTones[mode]} className={source ? undefined : className} {...props}>
      {labels[mode]}
    </StatusPill>
  )
  if (!source) return pill
  return (
    <span
      data-slot="context-mode"
      className={cn("inline-flex max-w-full min-w-0 items-center gap-inline text-xs", className)}
    >
      {pill}
      <span data-slot="context-mode-source" className="flex min-w-0 gap-inline text-muted-foreground">
        <span className="shrink-0">{labels.from}</span>
        <span className="min-w-0 truncate text-foreground" title={sourceThread.title ?? sourceThread.id}>
          {renderThreadLink ? renderThreadLink(sourceThread) : (sourceThread.title ?? sourceThread.id)}
        </span>
      </span>
    </span>
  )
}

export {
  AttemptStatusPill,
  ContextModePill,
  TaskStatusIcon,
  TaskStatusPill,
  attemptStatusLabels,
  attemptStatusLabelsEs,
  attemptStatusTones,
  contextModeLabels,
  contextModeLabelsEs,
  contextModeTones,
  taskStatusLabels,
  taskStatusAccentTones,
  taskStatusLabelsEs,
  taskStatusTones,
}
export type { ContextModeLabels, ContextModePillProps, TaskStatusIconProps }

import type { ComponentProps, ReactNode } from "react"

import type { TaskStatus } from "@/lib/agent-task-types"
import type { Tone } from "@/lib/tone"
import { cn } from "@/lib/utils"

/** What each status means, shared by the board's column accents and the status icons. */
const taskStatusAccentTones: Record<TaskStatus, Tone> = {
  proposed: "neutral",
  todo: "neutral",
  working: "info",
  review: "warning",
  blocked: "destructive",
  done: "success",
  cancelled: "neutral",
}

const toneIconColor: Record<Tone, string> = {
  neutral: "text-muted-foreground",
  info: "text-info",
  success: "text-success",
  warning: "text-warning",
  destructive: "text-destructive",
  violet: "text-violet",
}

const statusIconShape: Record<TaskStatus, ReactNode> = {
  proposed: <circle cx="8" cy="8" r="6" strokeDasharray="2.4 2.3" />,
  todo: <circle cx="8" cy="8" r="6" />,
  working: (
    <>
      <circle cx="8" cy="8" r="6" />
      <path d="M8 4.5a3.5 3.5 0 0 1 0 7Z" fill="currentColor" stroke="none" />
    </>
  ),
  review: (
    <>
      <circle cx="8" cy="8" r="6" />
      <path d="M8 4.5a3.5 3.5 0 1 1-3.5 3.5H8Z" fill="currentColor" stroke="none" />
    </>
  ),
  blocked: (
    <>
      <circle cx="8" cy="8" r="6.5" fill="currentColor" stroke="none" />
      <path d="M5.25 8h5.5" className="stroke-background" />
    </>
  ),
  done: (
    <>
      <circle cx="8" cy="8" r="6.5" fill="currentColor" stroke="none" />
      <path d="m5.25 8.1 1.8 1.8 3.7-3.7" className="stroke-background" />
    </>
  ),
  cancelled: (
    <>
      <circle cx="8" cy="8" r="6" />
      <path d="m4 12 8-8" />
    </>
  ),
}

type TaskStatusIconProps = Omit<ComponentProps<"svg">, "children"> & {
  status: TaskStatus
  /** Names the icon when no status text is beside it; without it, it is decorative. */
  label?: string
  /** Overrides the status's tone, as a board's `columnTones` does. */
  tone?: Tone
}

function TaskStatusIcon({ status, label, tone, className, ...props }: TaskStatusIconProps) {
  return (
    // oxlint-disable-next-line eskais/no-inline-icons -- status rings on a 16px grid, filled and cut out per status; no icon set has them
    <svg
      viewBox="0 0 16 16"
      fill="none"
      stroke="currentColor"
      strokeWidth="1.5"
      strokeLinecap="round"
      strokeLinejoin="round"
      data-slot="task-status-icon"
      data-status={status}
      data-tone={tone ?? taskStatusAccentTones[status]}
      role={label ? "img" : undefined}
      aria-label={label}
      aria-hidden={label ? undefined : true}
      className={cn("size-3.5 shrink-0", toneIconColor[tone ?? taskStatusAccentTones[status]], className)}
      {...props}
    >
      {statusIconShape[status]}
    </svg>
  )
}

export { TaskStatusIcon, taskStatusAccentTones }
export type { TaskStatusIconProps }
